    pub(super) fn parse_variant(parser: &mut Parser<'_>) -> Parsed<ValidationShape> {
        match parser.parse_word("a case of ValidationShape")? {
            "Unknown" => Ok(ValidationShape::Unknown),
            "Never" => Ok(ValidationShape::Never),
            "Undefined" => Ok(ValidationShape::Undefined),
            "Null" => Ok(ValidationShape::Null),
            "AnyObject" => Ok(ValidationShape::AnyObject),
            "Primitive" => parser.parse_nested(|parser| {
                let mut primitive = <ValidatedPrimitive>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "primitive" => primitive = parser.parse_enum(ValidatedPrimitive::from_name, "a member of ValidatedPrimitive")?,
                        _ => return parser.fail("a field of ValidationShape::Primitive"),
                    }
                }
                Ok(ValidationShape::Primitive { primitive })
            }),
            "BooleanLiteral" => parser.parse_nested(|parser| {
                let mut value = <bool>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_bool()?,
                        _ => return parser.fail("a field of ValidationShape::BooleanLiteral"),
                    }
                }
                Ok(ValidationShape::BooleanLiteral { value })
            }),
            "NumberLiteral" => parser.parse_nested(|parser| {
                let mut value = <f64>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_double()?,
                        _ => return parser.fail("a field of ValidationShape::NumberLiteral"),
                    }
                }
                Ok(ValidationShape::NumberLiteral { value })
            }),
            "StringLiteral" => parser.parse_nested(|parser| {
                let mut value = <StringId>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_string()?,
                        _ => return parser.fail("a field of ValidationShape::StringLiteral"),
                    }
                }
                Ok(ValidationShape::StringLiteral { value })
            }),
            "Array" => parser.parse_nested(|parser| {
                let mut element = <u32>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "element" => element = parser.parse_u32()?,
                        _ => return parser.fail("a field of ValidationShape::Array"),
                    }
                }
                Ok(ValidationShape::Array { element })
            }),
            "Tuple" => parser.parse_nested(|parser| {
                let mut elements = <Vec<u32>>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "elements" => elements = parser.parse_list(|parser| parser.parse_u32())?,
                        _ => return parser.fail("a field of ValidationShape::Tuple"),
                    }
                }
                Ok(ValidationShape::Tuple { elements })
            }),
            "Dictionary" => parser.parse_nested(|parser| {
                let mut value = <u32>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_u32()?,
                        _ => return parser.fail("a field of ValidationShape::Dictionary"),
                    }
                }
                Ok(ValidationShape::Dictionary { value })
            }),
            "Object" => parser.parse_nested(|parser| {
                let mut layout = <Option<LayoutId>>::default();
                let mut members = <Vec<ValidationMember>>::default();
                let mut undeclared = <UndeclaredMembers>::default();
                let mut undeclared_value = <Option<u32>>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "layout" => layout = Some(parser.parse_id::<LayoutId>("an id of kind Layout")?),
                        "members" => members = parser.parse_list(|parser| ValidationMember::parse_nested(parser))?,
                        "undeclared" => undeclared = parser.parse_enum(UndeclaredMembers::from_name, "a member of UndeclaredMembers")?,
                        "undeclaredValue" => undeclared_value = Some(parser.parse_u32()?),
                        _ => return parser.fail("a field of ValidationShape::Object"),
                    }
                }
                Ok(ValidationShape::Object { layout, members, undeclared, undeclared_value })
            }),
            "Union" => parser.parse_nested(|parser| {
                let mut arms = <Vec<u32>>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "arms" => arms = parser.parse_list(|parser| parser.parse_u32())?,
                        _ => return parser.fail("a field of ValidationShape::Union"),
                    }
                }
                Ok(ValidationShape::Union { arms })
            }),
            _ => parser.fail("a case of ValidationShape"),
        }
    }
