impl Function {
    pub fn print_fields(&self, printer: &mut Printer<'_>) {
        self.print_fields_after(printer, true);
        printer.print_body(&self.body);
    }
    pub(super) fn print_nested(&self, printer: &mut Printer<'_>) {
        printer.out.push('{');
        self.print_fields_after(printer, false);
        printer.out.push('}');
    }
    fn print_fields_after(&self, printer: &mut Printer<'_>, mut needs_blank: bool) {
        if let Some(value) = self.name {
            begin_field(printer, &mut needs_blank, "name");
            printer.print_string(value);
        }
        begin_field(printer, &mut needs_blank, "module");
        print_display(printer, self.module);
        if self.position != 0 {
            begin_field(printer, &mut needs_blank, "position");
            print_display(printer, self.position);
        }
        if !self.text.is_zero() {
            begin_field(printer, &mut needs_blank, "text");
            self.text.print_nested(printer);
        }
        if self.kind != FunctionKind::default() {
            begin_field(printer, &mut needs_blank, "kind");
            printer.out.push_str(self.kind.name());
        }
        if self.role != FunctionRole::default() {
            begin_field(printer, &mut needs_blank, "role");
            printer.out.push_str(self.role.name());
        }
        if !self.flags.is_empty() {
            begin_field(printer, &mut needs_blank, "flags");
            print_flags(printer, &FunctionFlags::NAMES, self.flags.0);
        }
        if self.length != 0 {
            begin_field(printer, &mut needs_blank, "length");
            print_display(printer, self.length);
        }
        if let Some(value) = self.enclosing_runtime_function {
            begin_field(printer, &mut needs_blank, "enclosingRuntimeFunction");
            print_display(printer, value.to_wire());
        }
        if !self.captures.is_empty() {
            begin_field(printer, &mut needs_blank, "captures");
            printer.out.push('[');
            printer.print_separated(&self.captures, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        begin_field(printer, &mut needs_blank, "thisType");
        self.this_type.print_nested(printer);
        if !self.parameters.is_empty() {
            begin_field(printer, &mut needs_blank, "parameters");
            printer.out.push('[');
            printer.print_separated(&self.parameters, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.results.is_empty() {
            begin_field(printer, &mut needs_blank, "results");
            printer.out.push('[');
            printer.print_separated(&self.results, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.function_types.is_empty() {
            begin_field(printer, &mut needs_blank, "functionTypes");
            printer.out.push('[');
            printer.print_separated(&self.function_types, |printer, element| print_display(printer, *element));
            printer.out.push(']');
        }
        if !self.builtin_members.is_empty() {
            begin_field(printer, &mut needs_blank, "builtinMembers");
            printer.out.push('[');
            printer.print_separated(&self.builtin_members, |printer, element| printer.out.push_str(element.name()));
            printer.out.push(']');
        }
        if !self.relations.is_zero() {
            begin_field(printer, &mut needs_blank, "relations");
            self.relations.print_nested(printer);
        }
    }
    pub fn parse_fields(parser: &mut Parser<'_>) -> Parsed<Function> {
        let mut record = Function::default();
        while let Some(name) = parser.next_field_name()? {
            match name {
                "name" => record.name = Some(parser.parse_string()?),
                "module" => record.module = parser.parse_id::<ModuleId>("an id of kind Module")?,
                "position" => record.position = parser.parse_u32()?,
                "text" => record.text = SourceRange::parse_nested(parser)?,
                "kind" => record.kind = parser.parse_enum(FunctionKind::from_name, "a member of FunctionKind")?,
                "role" => record.role = parser.parse_enum(FunctionRole::from_name, "a member of FunctionRole")?,
                "flags" => record.flags = parser.parse_flags(&FunctionFlags::NAMES, "a member of FunctionFlags").map(FunctionFlags)?,
                "length" => record.length = parser.parse_u32()?,
                "enclosingRuntimeFunction" => record.enclosing_runtime_function = Some(parse_external(parser, RuntimeFunction::from_wire, "a number of RuntimeFunction")?),
                "captures" => record.captures = parser.parse_list(|parser| DeclaredType::parse_nested(parser))?,
                "thisType" => record.this_type = DeclaredType::parse_nested(parser)?,
                "parameters" => record.parameters = parser.parse_list(|parser| DeclaredType::parse_nested(parser))?,
                "results" => record.results = parser.parse_list(|parser| DeclaredType::parse_nested(parser))?,
                "functionTypes" => record.function_types = parser.parse_list(|parser| parser.parse_id::<FunctionId>("an id of kind Function"))?,
                "builtinMembers" => record.builtin_members = parser.parse_list(|parser| parser.parse_enum(BuiltinId::from_name, "a member of Builtin"))?,
                "relations" => record.relations = FunctionRelations::parse_nested(parser)?,
                _ => return parser.fail("a field of Function"),
            }
        }
        record.body = parser.parse_body()?;
        Ok(record)
    }
    pub(super) fn parse_nested(parser: &mut Parser<'_>) -> Parsed<Function> {
        parser.parse_nested(Function::parse_fields)
    }
}

