impl Module {
    pub fn print_fields(&self, printer: &mut Printer<'_>) {
        self.print_fields_after(printer, true);
    }
    pub(super) fn print_nested(&self, printer: &mut Printer<'_>) {
        printer.out.push('{');
        self.print_fields_after(printer, false);
        printer.out.push('}');
    }
    fn print_fields_after(&self, printer: &mut Printer<'_>, mut needs_blank: bool) {
        begin_field(printer, &mut needs_blank, "path");
        printer.print_string(self.path);
        begin_field(printer, &mut needs_blank, "displayPath");
        printer.print_string(self.display_path);
        if self.kind != ModuleKind::default() {
            begin_field(printer, &mut needs_blank, "kind");
            printer.out.push_str(self.kind.name());
        }
        if !self.flags.is_empty() {
            begin_field(printer, &mut needs_blank, "flags");
            print_flags(printer, &ModuleFlags::NAMES, self.flags.0);
        }
        if self.export_rule != SyntheticExportRule::default() {
            begin_field(printer, &mut needs_blank, "exportRule");
            printer.out.push_str(self.export_rule.name());
        }
        if self.require_result != RequireResult::default() {
            begin_field(printer, &mut needs_blank, "requireResult");
            printer.out.push_str(self.require_result.name());
        }
        if self.external_kind != ExternalKind::default() {
            begin_field(printer, &mut needs_blank, "externalKind");
            printer.out.push_str(self.external_kind.name());
        }
        if let Some(value) = self.runtime_module {
            begin_field(printer, &mut needs_blank, "runtimeModule");
            printer.out.push_str(value.name());
        }
        if let Some(value) = self.referrer {
            begin_field(printer, &mut needs_blank, "referrer");
            print_display(printer, value);
        }
        if let Some(value) = self.body {
            begin_field(printer, &mut needs_blank, "body");
            print_display(printer, value);
        }
        if let Some(value) = self.exports_variable {
            begin_field(printer, &mut needs_blank, "exportsVariable");
            print_display(printer, value);
        }
        if let Some(value) = self.data {
            begin_field(printer, &mut needs_blank, "data");
            print_display(printer, value);
        }
        if !self.requests.is_empty() {
            begin_field(printer, &mut needs_blank, "requests");
            printer.out.push('[');
            printer.print_separated(&self.requests, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.exports.is_empty() {
            begin_field(printer, &mut needs_blank, "exports");
            printer.out.push('[');
            printer.print_separated(&self.exports, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.synthetic_exports.is_empty() {
            begin_field(printer, &mut needs_blank, "syntheticExports");
            printer.out.push('[');
            printer.print_separated(&self.synthetic_exports, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.required_names.is_empty() {
            begin_field(printer, &mut needs_blank, "requiredNames");
            printer.out.push('[');
            printer.print_separated(&self.required_names, |printer, element| element.print_nested(printer));
            printer.out.push(']');
        }
        if !self.positions.is_zero() {
            begin_field(printer, &mut needs_blank, "positions");
            self.positions.print_nested(printer);
        }
        if !self.function_text.is_empty() {
            begin_field(printer, &mut needs_blank, "functionText");
            printer.print_bytes(&self.function_text);
        }
    }
    pub fn parse_fields(parser: &mut Parser<'_>) -> Parsed<Module> {
        let mut record = Module::default();
        while let Some(name) = parser.next_field_name()? {
            match name {
                "path" => record.path = parser.parse_string()?,
                "displayPath" => record.display_path = parser.parse_string()?,
                "kind" => record.kind = parser.parse_enum(ModuleKind::from_name, "a member of ModuleKind")?,
                "flags" => record.flags = parser.parse_flags(&ModuleFlags::NAMES, "a member of ModuleFlags").map(ModuleFlags)?,
                "exportRule" => record.export_rule = parser.parse_enum(SyntheticExportRule::from_name, "a member of SyntheticExportRule")?,
                "requireResult" => record.require_result = parser.parse_enum(RequireResult::from_name, "a member of RequireResult")?,
                "externalKind" => record.external_kind = parser.parse_enum(ExternalKind::from_name, "a member of ExternalKind")?,
                "runtimeModule" => record.runtime_module = Some(parser.parse_enum(RuntimeModule::from_name, "a member of RuntimeModule")?),
                "referrer" => record.referrer = Some(parser.parse_id::<ModuleId>("an id of kind Module")?),
                "body" => record.body = Some(parser.parse_id::<FunctionId>("an id of kind Function")?),
                "exportsVariable" => record.exports_variable = Some(parser.parse_id::<VariableId>("an id of kind Variable")?),
                "data" => record.data = Some(parser.parse_id::<DataId>("an id of kind Data")?),
                "requests" => record.requests = parser.parse_list(|parser| ModuleRequest::parse_nested(parser))?,
                "exports" => record.exports = parser.parse_list(|parser| ModuleExport::parse_nested(parser))?,
                "syntheticExports" => record.synthetic_exports = parser.parse_list(|parser| SyntheticExport::parse_nested(parser))?,
                "requiredNames" => record.required_names = parser.parse_list(|parser| RequiredName::parse_nested(parser))?,
                "positions" => record.positions = SourcePositions::parse_nested(parser)?,
                "functionText" => record.function_text = parser.parse_bytes()?,
                _ => return parser.fail("a field of Module"),
            }
        }
        Ok(record)
    }
    pub(super) fn parse_nested(parser: &mut Parser<'_>) -> Parsed<Module> {
        parser.parse_nested(Module::parse_fields)
    }
}

