impl DataNode {
    pub(super) fn is_zero(&self) -> bool {
        matches!(self, DataNode::Undefined)
    }
    pub(super) fn print_variant(&self, printer: &mut Printer<'_>) {
        match self {
            DataNode::Undefined => printer.out.push_str("Undefined"),
            DataNode::Null => printer.out.push_str("Null"),
            DataNode::Hole => printer.out.push_str("Hole"),
            DataNode::Boolean { value } => {
                printer.out.push_str("Boolean{");
                let mut needs_blank = false;
                if *value {
                    begin_field(printer, &mut needs_blank, "value");
                    printer.out.push_str("true");
                }
                printer.out.push('}');
            }
            DataNode::Number { value } => {
                printer.out.push_str("Number{");
                let mut needs_blank = false;
                if value.to_bits() != 0 {
                    begin_field(printer, &mut needs_blank, "value");
                    printer.print_double(*value);
                }
                printer.out.push('}');
            }
            DataNode::String { value } => {
                printer.out.push_str("String{");
                let mut needs_blank = false;
                begin_field(printer, &mut needs_blank, "value");
                printer.print_string(*value);
                printer.out.push('}');
            }
            DataNode::BigInt { digits } => {
                printer.out.push_str("BigInt{");
                let mut needs_blank = false;
                begin_field(printer, &mut needs_blank, "digits");
                printer.print_string(*digits);
                printer.out.push('}');
            }
            DataNode::Array { contents, elements } => {
                printer.out.push_str("Array{");
                let mut needs_blank = false;
                begin_field(printer, &mut needs_blank, "contents");
                printer.print_type(*contents);
                if !elements.is_empty() {
                    begin_field(printer, &mut needs_blank, "elements");
                    printer.out.push('[');
                    printer.print_separated(elements, |printer, element| element.print_variant(printer));
                    printer.out.push(']');
                }
                printer.out.push('}');
            }
            DataNode::Object { layout, members } => {
                printer.out.push_str("Object{");
                let mut needs_blank = false;
                begin_field(printer, &mut needs_blank, "layout");
                print_display(printer, *layout);
                if !members.is_empty() {
                    begin_field(printer, &mut needs_blank, "members");
                    printer.out.push('[');
                    printer.print_separated(members, |printer, element| element.print_nested(printer));
                    printer.out.push(']');
                }
                printer.out.push('}');
            }
        }
    }
    pub(super) fn parse_variant(parser: &mut Parser<'_>) -> Parsed<DataNode> {
        match parser.parse_word("a case of DataNode")? {
            "Undefined" => Ok(DataNode::Undefined),
            "Null" => Ok(DataNode::Null),
            "Hole" => Ok(DataNode::Hole),
            "Boolean" => parser.parse_nested(|parser| {
                let mut value = <bool>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_bool()?,
                        _ => return parser.fail("a field of DataNode::Boolean"),
                    }
                }
                Ok(DataNode::Boolean { value })
            }),
            "Number" => parser.parse_nested(|parser| {
                let mut value = <f64>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_double()?,
                        _ => return parser.fail("a field of DataNode::Number"),
                    }
                }
                Ok(DataNode::Number { value })
            }),
            "String" => parser.parse_nested(|parser| {
                let mut value = <StringId>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "value" => value = parser.parse_string()?,
                        _ => return parser.fail("a field of DataNode::String"),
                    }
                }
                Ok(DataNode::String { value })
            }),
            "BigInt" => parser.parse_nested(|parser| {
                let mut digits = <StringId>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "digits" => digits = parser.parse_string()?,
                        _ => return parser.fail("a field of DataNode::BigInt"),
                    }
                }
                Ok(DataNode::BigInt { digits })
            }),
            "Array" => parser.parse_nested(|parser| {
                let mut contents = <TypeId>::default();
                let mut elements = <Vec<DataNode>>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "contents" => contents = parser.parse_type()?,
                        "elements" => elements = parser.parse_list(|parser| DataNode::parse_variant(parser))?,
                        _ => return parser.fail("a field of DataNode::Array"),
                    }
                }
                Ok(DataNode::Array { contents, elements })
            }),
            "Object" => parser.parse_nested(|parser| {
                let mut layout = <LayoutId>::default();
                let mut members = <Vec<DataMember>>::default();
                while let Some(name) = parser.next_field_name()? {
                    match name {
                        "layout" => layout = parser.parse_id::<LayoutId>("an id of kind Layout")?,
                        "members" => members = parser.parse_list(|parser| DataMember::parse_nested(parser))?,
                        _ => return parser.fail("a field of DataNode::Object"),
                    }
                }
                Ok(DataNode::Object { layout, members })
            }),
            _ => parser.fail("a case of DataNode"),
        }
    }
}

